 const modules=useMemo(()=>profile?roleModules[profile.role]:[],[profile]);
 const set=(key:string,value:string)=>setF(old=>({...old,[key]:value}));
 const loadLookups=useCallback(async()=>{
  const learnerQuery=profile?.role==="bursar"
   ? ((supabase as any).rpc("get_finance_learners") as any)
   : supabase.from("learners").select("id,full_name,admission_number,class_id").order("full_name").limit(500);
  const profileQuery=profile?.role==="admin"
   ? supabase.from("profiles").select("id,full_name,role,approval_status,phone").order("created_at",{ascending:false}).limit(200)
   : Promise.resolve({data:[] as Row[],error:null});
  const [l,c,s,t,p,g]=await Promise.all([
   learnerQuery,
   supabase.from("classes").select("id,name,level_order").eq("active",true).order("level_order"),
   supabase.from("subjects").select("id,name").eq("active",true).order("name"),
   supabase.from("academic_terms").select("id,name,academic_year,term_number").order("academic_year",{ascending:false}),
   profileQuery,
   (supabase as any).from("subject_grade_levels").select("grade_level,subject_id,is_optional")
  ]);
  const a=profile?.role==="bursar"||profile?.role==="student"
   ? {data:[] as Row[]}
   : await supabase.from("assessments").select("id,title,class_id").order("created_at",{ascending:false}).limit(300);
  const links=profile?.role==="admin"?await (supabase as any).from("student_learner_links").select("user_id,learner_id,linked_at"): {data:[] as Row[]};
  setAssessmentOptions(a.data??[]);setLearners(l.data??[]);setClasses(c.data??[]);setSubjects(s.data??[]);setSubjectGradeLevels(g.data??[]);setTerms(t.data??[]);setProfiles(p.data??[]);setStudentLinks(links.data??[]);setLinkSelections(Object.fromEntries((links.data??[]).map((x:Row)=>[x.user_id,x.learner_id])));
 },[supabase,profile?.role]);
 const loadRows=useCallback(async(key:ModuleKey)=>{
  setLoading(true);setNotice("");
  if(key==="my-records"){
   if(profile?.role!=="student"){setRows([]);setNotice("This section is reserved for student accounts.");setLoading(false);return;}
   const link=await (supabase as any).from("student_learner_links").select("learner_id").eq("user_id",profile.id).maybeSingle();
   if(link.error||!link.data){setRows([]);setNotice(link.error?.message??"Your account has not yet been linked to a learner record. Please contact the school administrator.");setLoading(false);return;}
   const learnerId=link.data.learner_id;
   const [learnerResult,attendanceResult,marksResult,feesResult]=await Promise.all([
    supabase.from("learners").select("full_name,admission_number").eq("id",learnerId).maybeSingle(),
    supabase.from("attendance").select("attendance_date,status,note").eq("learner_id",learnerId).order("attendance_date",{ascending:false}).limit(100),
    supabase.from("marks").select("score,maximum_score,grade,feedback,competency_progress,created_at").eq("learner_id",learnerId).order("created_at",{ascending:false}).limit(100),
    supabase.from("fee_payments").select("amount_kes,payment_method,receipt_number,status,paid_at").eq("learner_id",learnerId).eq("status","approved").order("paid_at",{ascending:false}).limit(100)
   ]);
   const combined:Row[]=[
    ...(attendanceResult.data??[]).map(x=>({record:"Attendance",date:x.attendance_date,details:x.note||"Daily attendance",status:x.status})),
    ...(marksResult.data??[]).map(x=>({record:"Assessment",date:x.created_at,details:[x.grade,x.score!==null?String(x.score)+"/"+String(x.maximum_score??"—"):"",x.feedback,x.competency_progress].filter(Boolean).join(" · "),status:"Recorded"})),
    ...(feesResult.data??[]).map(x=>({record:"Fee payment",date:x.paid_at,details:"KES "+x.amount_kes+" · "+x.payment_method+" · "+(x.receipt_number||"No receipt number"),status:x.status}))
   ].sort((a,b)=>new Date(b.date).getTime()-new Date(a.date).getTime());
   setRows(combined);setNotice(learnerResult.data?learnerResult.data.full_name+" · Admission "+learnerResult.data.admission_number+(combined.length?"":" · No attendance, assessment or approved payment records are available yet."):learnerResult.error?.message??"Learner record is unavailable.");setLoading(false);return;
  }
  const table:Record<string,string>={learners:"learners",attendance:"attendance",assessments:"assessments",results:"marks",classes:"classes",fees:"fee_payments",approvals:"profiles",notices:"notices",news:"school_posts",website:"school_events"};
  if(!table[key]){setRows([]);setLoading(false);return;}
  if(key==="website"){
   const [events,photos]=await Promise.all([
    supabase.from("school_events").select("*").order("created_at",{ascending:false}).limit(100),
    supabase.from("school_gallery").select("*").order("created_at",{ascending:false}).limit(100)
   ]);
   const combined=[...(events.data??[]),...(photos.data??[])].sort((a,b)=>new Date(b.created_at).getTime()-new Date(a.created_at).getTime());
   setRows(combined);setNotice(events.error?.message??photos.error?.message??(!combined.length?"No website content yet. Use the forms below to add the first item.":""));setLoading(false);return;
  }
  const result=await (supabase.from(table[key] as any) as any).select("*").order("created_at",{ascending:false}).limit(100);
  setRows(result.data??[]);setNotice(result.error?.message??(!result.data?.length?"No records yet. Use the form below to add the first record.":""));setLoading(false);
 },[supabase]);
 useEffect(()=>{let alive=true; (async()=>{
  const {data:{session}}=await supabase.auth.getSession();if(!session){router.replace("/portal/");return;}
  const {data,error}=await supabase.from("profiles").select("id,full_name,role,approval_status").eq("id",session.user.id).single();
  if(!alive)return;if(error||!data){setStatus("blocked");setMessage("Your school profile could not be verified.");return;}
  setProfile(data as Profile);if(data.approval_status!=="approved"){setStatus("blocked");setMessage("Your account is awaiting school approval.");return;}
  setStatus("ready");setMessage("Signed in securely. Database permissions control the records you can access.");
 })();return()=>{alive=false}},[router,supabase]);
 useEffect(()=>{if(status==="ready"){void loadLookups();void loadRows(active)}},[status,active,loadLookups,loadRows]);
 const submit=async(e:FormEvent<HTMLFormElement>,table:string,payload:Row,after?:(data:Row)=>void)=>{
  e.preventDefault();setBusy(true);setError("");setSuccess("");
  const result=await (supabase.from(table as any) as any).insert(payload).select("*").single();
  setBusy(false);
  if(result.error){setError(result.error.message);return;}
  setSuccess("Saved successfully.");after?.(result.data);setF({date:today(),study_mode:"day",status:"present",method:"mpesa",audience:"all",role:"teacher",approval_status:"approved",year:String(new Date().getFullYear()),term_number:"1"});
  await loadRows(active);await loadLookups();
 };
 const saveGallery=async(e:FormEvent<HTMLFormElement>)=>{
  e.preventDefault();
  if(!profile){setError("Your administrator session could not be verified. Please sign in again.");return;}
  const activeProfile=profile;
  setBusy(true);setError("");setSuccess("");
  let imageUrl=(f.gallery_image??"").trim();let uploadedPath:string|null=null;
  if(galleryFile){
   const allowed=["image/jpeg","image/png","image/webp","image/gif"];
   if(!allowed.includes(galleryFile.type)){setBusy(false);setError("Choose a JPG, PNG, WebP or GIF image.");return;}
   if(galleryFile.size>8*1024*1024){setBusy(false);setError("The image must be 8 MB or smaller.");return;}
   const ext=galleryFile.type==="image/jpeg"?"jpg":galleryFile.type.split("/")[1];
   uploadedPath=activeProfile.id+"/"+Date.now()+"-"+crypto.randomUUID()+"."+ext;
   const upload=await supabase.storage.from("school-gallery").upload(uploadedPath,galleryFile,{cacheControl:"3600",contentType:galleryFile.type,upsert:false});
   if(upload.error){setBusy(false);setError("Photo upload failed: "+upload.error.message);return;}
   imageUrl=supabase.storage.from("school-gallery").getPublicUrl(uploadedPath).data.publicUrl;
  }
  if(!imageUrl){setBusy(false);setError("Choose a photo from your phone or enter an HTTPS image URL.");return;}
  if(!galleryFile&&!/^https:\/\//i.test(imageUrl)){setBusy(false);setError("The image URL must start with HTTPS.");return;}
  const result=await supabase.from("school_gallery").insert({title:f.gallery_title,description:f.gallery_description||"",image_url:imageUrl,category:f.gallery_category||"School life",display_order:Number(f.gallery_order||0),status:f.gallery_status||"draft",created_by:activeProfile.id});
  if(result.error){
   if(uploadedPath) await supabase.storage.from("school-gallery").remove([uploadedPath]);
   setBusy(false);setError(result.error.message);return;
  }
  setBusy(false);setSuccess("Photograph uploaded and saved.");setGalleryFile(null);
  setF({date:today(),study_mode:"day",status:"present",method:"mpesa",audience:"all",role:"teacher",approval_status:"approved",year:String(new Date().getFullYear()),term_number:"1",grade_level:"Grade 1"});
  await loadRows("website");await loadLookups();
 };
